function main(params, state) {
  var p = state.player;
  if (!p || p.dead) return false;
  var v = p.vitals || {};
  var air = Number(v.air);
  if (!isFinite(air)) return false;
  var flags = p.flags || {};
  if (!flags.inWater) return false;
  var th = params && typeof params.airThreshold === 'number' ? params.airThreshold : 40;
  return air <= th;
}
